            for pos in range(m + 1):
                if pos == 0:
                    inc = dist[depot][cid] + dist[cid][r[0]] - dist[depot][r[0]]
                elif pos == m:
                    inc = dist[r[m - 1]][cid] + dist[cid][depot] - dist[r[m - 1]][depot]
                else:
                    inc = dist[r[pos - 1]][cid] + dist[cid][r[pos]] - dist[r[pos - 1]][r[pos]]
                key = (inc, rid, pos)
                if best is None or key < best[0]:
                    best = (key, rid, pos)
        if best is None:
            routes.append([cid])
            load.append(demands[cid])
        else:
            _, rid, pos = best
            routes[rid].insert(pos, cid)
            load[rid] += demands[cid]

    # --- Phase 3: Local search to reduce cost while maintaining feasibility ---
    def two_opt_improve():
        improved = True
        iter_limit = 2 * max(1, len(routes))
        it = 0
        while improved and it < iter_limit:
            improved = False
            it += 1
            for rid in range(len(routes)):
                r = routes[rid]
                m = len(r)
                if m < 4:
                    continue
                for i in range(m - 1):
                    a = r[i]
                    a_prev = depot if i == 0 else r[i - 1]
                    for k in range(i + 2, m):
                        if i == 0 and k == m - 1:
                            continue
                        b = r[k]
                        b_next = depot if k == m - 1 else r[k + 1]
                        cur = dist[a_prev][a] + dist[b][b_next]
                        new = dist[a_prev][b] + dist[a][b_next]
                        if new < cur:
                            routes[rid] = r[:i + 1] + r[i + 1:k + 1][::-1] + r[k + 1:]
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
        return improved

    def relocate_improve():
        base_cost = total_cost(routes)
        best_overall = None  # (new_cost, from_rid, to_rid, from_pos, to_pos, v)
        nn = instance.get('nearest_neighbors', {})
        # Deterministic small neighborhood
        for fr in range(len(routes)):
            rfrom = routes[fr]
            m = len(rfrom)
            for fp in range(m):
                v = rfrom[fp]
                cand_targets = []
                neigh = nn.get(str(v), None)
                if neigh:
                    for u in neigh:
                        if u in route_of and route_of[u] not in cand_targets and route_of[u] != fr:
                            cand_targets.append(route_of[u])
                        if len(cand_targets) >= 6:
                            break
                # Always include at least a few deterministic routes
                for tr in range(len(routes)):
                    if tr != fr and tr not in cand_targets:
                        cand_targets.append(tr)
                    if len(cand_targets) >= 10:
                        break

                for tr in cand_targets:
                    rto = routes[tr]
                    if load[tr] + demands[v] > cap:
                        continue
                    if not rto:
                        positions = [0]
                    else:
                        positions = [0, len(rto)]
                        if neigh:
                            # try inserting near a nearest neighbor that is in route tr
                            for u in neigh:
                                if u in route_of and route_of[u] == tr:
                                    idx_u = routes[tr].index(u)
                                    positions += [idx_u, min(len(rto), idx_u + 1)]
                                    break
                        if len(rto) > 2:
                            positions += [len(rto) // 2, max(1, len(rto) // 2 - 1)]
                    # dedupe
                    ps = []
                    seenp = set()
                    for p in positions:
                        p = max(0, min(len(rto), p))
                        if p not in seenp:
                            seenp.add(p)
                            ps.append(p)
                    for tp in ps:
                        # Apply tentative move and compute delta by recomputing involved routes
                        # Create new routes for fr and tr
                        new_from = rfrom[:fp] + rfrom[fp + 1:]
                        new_to = rto[:tp] + [v] + rto[tp:]
                        if route_load(new_from) > cap:
                            continue
                        if route_load(new_to) > cap:
                            continue
                        if fr == tr:
                            continue
                        # Cost recompute for affected routes only
                        old = route_cost(rfrom) + route_cost(rto)
                        new = route_cost(new_from) + route_cost(new_to)
                        new_cost = base_cost - old + new
                        if best_overall is None or new_cost < best_overall[0]:
                            best_overall = (new_cost, fr, tr, fp, tp, v, new_from, new_to)

        if best_overall is None:
            return False
        _, fr, tr, fp, tp, v, new_from, new_to = best_overall
        routes[fr] = new_from
        routes[tr] = new_to
        load[fr] = route_load(new_from)
        load[tr] = route_load(new_to)

        # Clean empty routes deterministically
        new_routes = []
        new_route_of = {}
        new_load = []
        for rid, r in enumerate(routes):
            if r:
                new_route_of[rid] = len(new_routes)  # temp mapping
                new_routes.append(r)
                new_load.append(route_load(r))
        # rebuild route_of properly
        routes = new_routes
        route_of.clear()
        load = new_load
        for rid, r in enumerate(routes):
            for x in r:
                route_of[x] = rid
        return True

    # Apply local improvements (bounded)
    two_opt_improve()
    relocate_improve()

    # --- Final feasibility repair: split any infeasible route deterministically ---
    # (Should be rare, but ensures we always return feasible routes.)
    feasible_routes = []
    for r in routes:
        if route_load(r) <= cap:
            feasible_routes.append(r)
            continue
        # Greedy split preserving order
        cur = []
        cur_load = 0
        for v in r:
            d = demands[v]
            if cur and cur_load + d > cap:
                feasible_routes.append(cur)
                cur = [v]
                cur_load = d
            else:
                cur.append(v)
                cur_load += d
        if cur:
            feasible_routes.append(cur)
    routes = feasible_routes

    # Ensure all customers are present exactly once across all routes
    used = set()
    out = []
    for r in routes:
        rr = []
        for v in r:
            if v in used:
                continue
            used.add(v)
            rr.append(v)
        if rr:
            out.append(rr)
    missing = [cid for cid in cust_ids if cid not in used]
    for cid in missing:
        # insert into first feasible route by deterministic cheapest end
        best = None
        for rid, r in enumerate(out):
            if route_load(r) + demands[cid] > cap:
                continue
            if not r:
                inc = dist[depot][cid] * 2
                key = (inc, rid, 0)
            else:
                inc0 = dist[depot][cid] + dist[cid][r[0]] - dist[depot][r[0]]
                incm = dist[r[-1]][cid] + dist[cid][depot] - dist[r[-1]][depot]
                if inc0 <= incm:
                    key = (inc0, rid, 0)
                else:
                    key = (incm, rid, len(r))
            if best is None or key < best[0]:
                best = (key, rid)
        if best is None:
            out.append([cid])
        else:
            _, rid, pos = best[0]
            out[rid].insert(pos, cid)

    return out
